function ChatWidget() {
  const [open, setOpen] = useState(false);
  const [msgs, setMsgs] = useState([{ from: "bot", text: "Habari! I\'m Murango\'s campaign assistant. How can I help you today?" }]);
  const [input, setInput] = useState("");
  const send = () => {
    if (!input.trim()) return;
    const userMsg = { from: "user", text: input };
    setMsgs(m => [...m, userMsg]);
    setInput("");
    setTimeout(() => {
      const responses = [
        "Thank you for your message! Hon. Murango is committed to serving Kirinyaga constituents.",
        "Please join us at our next rally! Check the Events section for details.",
        "For urgent matters, reach us via WhatsApp: +254 712 345 678",
        "Murango 2027 – Building a Better Kirinyaga together!",
      ];
      setMsgs(m => [...m, { from: "bot", text: responses[Math.floor(Math.random() * responses.length)] }]);
    }, 1000);
  };
  return (
    <div className="fixed bottom-6 right-6 z-50">
      {open && (
        <div className="mb-3 w-80 bg-gray-900 border border-green-700 rounded-2xl shadow-2xl overflow-hidden animate-slideUp">
          <div className="bg-gradient-to-r from-green-800 to-green-700 px-4 py-3 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <div className="w-2 h-2 bg-green-400 rounded-full animate-pulse"></div>
              <span className="text-white font-bold text-sm">Murango Campaign HQ</span>
            </div>
            <button onClick={() => setOpen(false)} className="text-white/60 hover:text-white text-lg">✕</button>
          </div>
          <div className="h-48 overflow-y-auto p-4 space-y-2 bg-gray-900/90">
            {msgs.map((m, i) => (
              <div key={i} className={`flex ${m.from === "user" ? "justify-end" : "justify-start"}`}>
                <div className={`max-w-[80%] px-3 py-2 rounded-xl text-sm ${m.from === "user" ? "bg-green-700 text-white" : "bg-gray-700 text-gray-100"}`}>
                  {m.text}
                </div>
              </div>
            ))}
          </div>
          <div className="p-3 border-t border-gray-700 flex gap-2">
            <input value={input} onChange={e => setInput(e.target.value)}
              onKeyDown={e => e.key === "Enter" && send()}
              placeholder="Type a message..."
              className="flex-1 bg-gray-800 text-white text-sm rounded-lg px-3 py-2 outline-none border border-gray-700 focus:border-green-500 transition-colors" />
            <button onClick={send}
              className="bg-green-700 hover:bg-green-600 text-white px-3 py-2 rounded-lg transition-colors text-sm font-bold">→</button>
          </div>
        </div>
      )}
      <button onClick={() => setOpen(o => !o)}
        className="w-14 h-14 bg-green-700 hover:bg-green-600 text-white rounded-full shadow-lg flex items-center justify-center text-2xl hover:scale-110 transition-all duration-200 border-2 border-green-400/50">
        {open ? "✕" : "💬"}
      </button>
    </div>
  );
}

